resources.string:
GuideHighlight(
 holeRectProvider = { anchor ->
 // anchor 是屏幕坐标，返回值使用同一坐标系
 Rect(
 anchor.centerX() - halfWidthPx,
 anchor.centerY() - halfHeightPx,
 anchor.centerX() + halfWidthPx,
 anchor.centerY() + halfHeightPx
 )
 }
)

GuideHighlight(
 maskRectProvider = { container, anchor ->
 Rect(anchor).apply { inset(-padX, -padY) }
 }
)
GuideStep(
 ...,
 passThroughOutsideMask = true
)

GuideContent.CustomBinding(
 create = { inflater, parent ->
 ViewGuideCustomDemoBinding.inflate(inflater, parent, false)
 },
 bind = { binding, session ->
 binding.customGuideNext.setOnClickListener { session.next() }
 }
)
